INSERT IGNORE INTO `ft_products` (name, icon, category_id, default_unit, expiry_tip, active, created_at, updated_at) VALUES ('Yogurt bianco', 'yogurt', (SELECT id FROM `ft_categories` WHERE name = 'Latticini e uova'), 'g', 'Lo yogurt chiuso è spesso buono anche alcuni giorni dopo la data: se non è gonfio e non ha muffa o odore anomalo, assaggialo prima di buttarlo.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP());
